def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            expired_keys = []
            for k, (_, write_time) in cache.items():
                if t >= write_time + ttl:
                    expired_keys.append(k)
            for k in expired_keys:
                del cache[k]

            # If key already exists, remove it (will be re-added as most recent)
            if key in cache:
                del cache[key]

            # If cache is at capacity and key is new, evict LRU
            if len(cache) >= capacity:
                # Remove the least recently used (first item in OrderedDict)
                cache.popitem(last=False)

            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = []
            for k, (_, write_time) in cache.items():
                if t >= write_time + ttl:
                    expired_keys.append(k)
            for k in expired_keys:
                del cache[k]

            # Check if key exists
            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

